ALTER TABLE public.order_refund_requests ADD COLUMN IF NOT EXISTS execution_verified boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.guard_legacy_refund_after_combined() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; BEGIN IF TG_OP='UPDATE' THEN RETURN NEW; END IF; IF TG_TABLE_NAME='deposit_refunds' THEN SELECT inquiry_id INTO owner FROM public.offer_payment_links WHERE id=NEW.link_id; ELSIF TG_TABLE_NAME='rental_order_refunds' THEN SELECT inquiry_id INTO owner FROM public.rental_refund_bases WHERE id=NEW.basis_id; ELSE SELECT rental_inquiry_id INTO owner FROM public.inquiry_invoices WHERE id=NEW.credit_note_id; END IF; PERFORM 1 FROM public.rental_inquiries WHERE id=owner FOR UPDATE; IF EXISTS(SELECT 1 FROM public.order_refund_requests WHERE inquiry_id=owner AND status NOT IN ('failed','canceled')) THEN RAISE EXCEPTION 'Gemeinsame Erstattung bereits beauftragt; verbleibenden Anspruch dort prüfen' USING ERRCODE='PT409'; END IF; RETURN NEW; END $$;
CREATE TRIGGER aa_combined_refund_lock BEFORE INSERT ON public.deposit_refunds FOR EACH ROW EXECUTE FUNCTION public.guard_legacy_refund_after_combined();
CREATE TRIGGER aa_combined_refund_lock BEFORE INSERT ON public.rental_order_refunds FOR EACH ROW EXECUTE FUNCTION public.guard_legacy_refund_after_combined();
CREATE TRIGGER aa_combined_refund_lock BEFORE INSERT ON public.credit_note_refunds FOR EACH ROW EXECUTE FUNCTION public.guard_legacy_refund_after_combined();